sys_script.script:
(function executeRule(current, previous /*null when async*/) {
    // 1. New Test Request (Insert with status = '1' or changes to '1')
    if (current.status == '1' && (current.operation() == 'insert' || previous.status != '1')) {
        gs.eventQueue('x_2223823_apollo_0.lab_new_request', current, '', '');
        gs.eventQueue('x_hospital.lab_new_request', current, '', '');
    }

    // 2. Sample Received (Status changes to '4')
    if (current.status == '4' && (current.operation() == 'insert' || previous.status != '4')) {
        gs.eventQueue('x_2223823_apollo_0.lab_sample_received', current, '', '');
        gs.eventQueue('x_hospital.lab_sample_received', current, '', '');
    }

    // 3. Equipment Unavailable / Disruption (Status moves to '10' Needs Rescheduling)
    if (current.status == '10' && previous.status != '10') {
        gs.eventQueue('x_2223823_apollo_0.lab_equipment_unavailable', current, '', '');
        gs.eventQueue('x_hospital.lab_equipment_unavailable', current, '', '');
    }
})(current, previous);
